mapper.update:
UPDATE TRIAL_PARTICIPATION
   SET STATUS = 'WITHDRAWN'
 WHERE PARTICIPATION_NO = #{participationNo}
   AND MEMBER_NO = #{memberNo}
   AND STATUS = 'APPLIED'

UPDATE TRIAL_PARTICIPATION
   SET STATUS = 'APPROVED',
       APPROVED_AT = SYSDATE
 WHERE PARTICIPATION_NO = #{participationNo}
   AND BUSINESS_NO = #{businessNo}
   AND STATUS = 'APPLIED'

UPDATE TRIAL_PARTICIPATION
   SET STATUS = 'REJECTED',
       APPROVED_AT = NULL
 WHERE PARTICIPATION_NO = #{participationNo}
   AND BUSINESS_NO = #{businessNo}
   AND STATUS = 'APPLIED'
